func TestChunkText(t *testing.T) {
	// 构造 3 个段落，每段约 500 字
	p1 := strings.Repeat("a", 500)
	p2 := strings.Repeat("b", 500)
	p3 := strings.Repeat("c", 500)
	text := p1 + "\n\n" + p2 + "\n\n" + p3

	// chunkSize=800, overlap=50 → 应产生 2 个块
	chunks := chunkText(text, 800, 50)
	if len(chunks) != 2 {
		t.Fatalf("期望 2 个块，实际 %d: %v", len(chunks), chunks)
	}
	// 第一块应包含 p1+p2
	if !strings.Contains(chunks[0], p1) || !strings.Contains(chunks[0], p2) {
		t.Errorf("第一块应包含 p1 和 p2")
	}
	// 第二块应包含重叠部分 + p3
	if !strings.Contains(chunks[1], p3) {
		t.Errorf("第二块应包含 p3")
	}
}

