func (m Model) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	// 弹窗优先拦截按键
	if m.popup != nil {
		switch msg.String() {
		case "esc", "q":
			m.popup = nil
			return m, nil
		case "up", "k":
			if m.popup.offset > 0 {
				m.popup.offset--
			}
			return m, nil
		case "down", "j":
			if m.popup.offset < len(m.popup.lines)-1 {
				m.popup.offset++
			}
			return m, nil
		case "pgup":
			popupScroll(m.popup, -max(1, m.height/2))
			return m, nil
		case "pgdown", " ":
			popupScroll(m.popup, max(1, m.height/2))
			return m, nil
		case "home":
			m.popup.offset = 0
			return m, nil
		case "end":
			m.popup.offset = max(0, len(m.popup.lines)-1)
			return m, nil
		}
		return m, nil
	}

	switch m.view {
	case viewFilter:
		return m.handleFilterKey(msg)
	case viewReader:
		return m.handleReaderKey(msg)
	default:
		return m.handleListKey(msg)
	}
}

func popupScroll(p *popupState, delta int) {
	p.offset += delta
	if p.offset < 0 {
		p.offset = 0
	}
	if p.offset >= len(p.lines) {
		p.offset = len(p.lines) - 1
	}
}

