func stripANSI(s string) string {
	var b strings.Builder
	inEsc := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == 0x1b {
			inEsc = true
			continue
		}
		if inEsc {
			if c >= 0x40 && c <= 0x7e {
				inEsc = false
			}
			continue
		}
		b.WriteByte(c)
	}
	return b.String()
}

