// ── 弹窗叠加 ─────────────────────────────────────────────────

// overlayPopup 将弹窗叠加在基础视图之上。
// 弹窗居中显示，带边框和标题，可滚动，半透明背景遮罩。
func overlayPopup(base string, p *popupState, termW, termH int) string {
	if termW < 20 {
		termW = 20
	}
	if termH < 6 {
		termH = 6
	}

	// 弹窗大小：取终端 70% 宽、80% 高，最小 40×8
	pw := termW * 7 / 10
	if pw < 40 {
		pw = 40
	}
	if pw > termW-4 {
		pw = termW - 4
	}
	ph := termH * 8 / 10
	if ph < 6 {
		ph = 6
	}
	if ph > termH-2 {
		ph = termH - 2
	}

	// 构建弹窗内容
	var popupSB strings.Builder
	// 标题栏
	title := p.title
	if len([]rune(title)) > pw-4 {
		title = string([]rune(title)[:pw-7]) + "…"
	}
	popupSB.WriteString(styleCursor.Render("┌─ "+title+" "))
	rem := pw - 3 - len([]rune(title))
	if rem > 0 {
		popupSB.WriteString(strings.Repeat("─", rem))
	}
	popupSB.WriteString("┐\n")

	// 内容区域
	contentH := ph - 4 // 减去边框行（顶/底/空行/帮助）
	if contentH < 1 {
		contentH = 1
	}

	if p.loading {
		for i := 0; i < contentH; i++ {
			if i == contentH/2 {
				popupSB.WriteString(fmt.Sprintf("│ %-*s │\n", pw-2, "  正在生成，请稍候…"))
			} else {
				popupSB.WriteString(fmt.Sprintf("│ %-*s │\n", pw-2, ""))
			}
		}
	} else if p.err != "" {
		popupSB.WriteString(fmt.Sprintf("│ %-*s │\n", pw-2, styleErr.Render("错误: "+p.err)))
		for i := 1; i < contentH; i++ {
			popupSB.WriteString(fmt.Sprintf("│ %-*s │\n", pw-2, ""))
		}
	} else if len(p.lines) > 0 {
		start := p.offset
		if start < 0 {
			start = 0
		}
		if start >= len(p.lines) {
			start = len(p.lines) - 1
		}
		for i := 0; i < contentH; i++ {
			li := start + i
			if li < len(p.lines) {
				line := p.lines[li]
				// 截断过长行
				if len([]rune(line)) > pw-4 {
					line = string([]rune(line)[:pw-7]) + "…"
				}
				popupSB.WriteString(fmt.Sprintf("│ %-*s │\n", pw-2, line))
			} else {
				popupSB.WriteString(fmt.Sprintf("│ %-*s │\n", pw-2, ""))
			}
		}
	} else {
		for i := 0; i < contentH; i++ {
			popupSB.WriteString(fmt.Sprintf("│ %-*s │\n", pw-2, ""))
		}
	}

	// 底部帮助
	popupSB.WriteString(fmt.Sprintf("│ %-*s │\n", pw-2, styleHelp.Render("Esc 关闭  ↑↓ 滚动  PgUp/PgDn 翻页")))
	popupSB.WriteString("└" + strings.Repeat("─", pw-2) + "┘")

	popup := popupSB.String()

	// 叠加：逐行覆盖基础视图
	baseLines := strings.Split(base, "\n")
	popupLines := strings.Split(popup, "\n")

	// 弹窗起始行列
	startRow := (termH - len(popupLines)) / 2
	if startRow < 0 {
		startRow = 0
	}
	startCol := (termW - pw) / 2
	if startCol < 0 {
		startCol = 0
	}

	// 构建结果
	var resultSB strings.Builder
	for row := 0; row < termH; row++ {
		if row >= startRow && row < startRow+len(popupLines) {
			popupRow := row - startRow
			popupLine := popupLines[popupRow]
			// 合并基础行和弹窗行
			var lineSB strings.Builder
			if row < len(baseLines) {
				// 前半部分：基础视图内容（但被弹窗覆盖部分变暗）
				baseLine := baseLines[row]
				baseRunes := []rune(baseLine)
				// 左侧（弹出前）
				if startCol > 0 && startCol < len(baseRunes) {
					lineSB.WriteString(styleDim.Render(string(baseRunes[:startCol])))
				} else if startCol > 0 {
					lineSB.WriteString(styleDim.Render(strings.Repeat(" ", startCol)))
				}
				// 弹窗
				lineSB.WriteString(popupLine)
				// 右侧（弹出后）
				rightStart := startCol + len([]rune(popupLine))
				if rightStart < len(baseRunes) {
					lineSB.WriteString(styleDim.Render(string(baseRunes[rightStart:])))
				}
			} else {
				// 基础视图不够行，左侧填充空白
				if startCol > 0 {
					lineSB.WriteString(styleDim.Render(strings.Repeat(" ", startCol)))
				}
				lineSB.WriteString(popupLine)
			}
			resultSB.WriteString(lineSB.String())
			resultSB.WriteString("\n")
		} else if row < len(baseLines) {
			// 非弹窗行：显示基础内容（变暗以突出弹窗）
			resultSB.WriteString(styleDim.Render(baseLines[row]))
			resultSB.WriteString("\n")
		} else {
			resultSB.WriteString("\n")
		}
	}
	return resultSB.String()
}

