func parseBriefResult(text string) *llm.BriefResult {
	r := &llm.BriefResult{}
	currentKey := ""
	var sb strings.Builder
	for _, line := range strings.Split(text, "\n") {
		trimmed := strings.TrimSpace(line)
		switch trimmed {
		case "## 背景", "## 各方立场", "## 影响", "## 后续关注":
			r.setSectionStr(currentKey, sb.String())
			currentKey = trimmed
			sb.Reset()
			continue
		}
		if currentKey != "" {
			if sb.Len() > 0 {
				sb.WriteByte('\n')
			}
			sb.WriteString(line)
		}
	}
	r.setSectionStr(currentKey, sb.String())
	return r
}

